'use strict'

// The hearts fill up, as in the ROM (a piece of the Triforce, the fairy of a pond): the partial heart ($0670) grows by 9
// every frame, a heart full once it overflows (the last one stays full, $FF); it shows empty at 0, half up to $7F,
// full from $80
const REFILL_STEP = 9
const PARTIAL_FULL = 0xff
const PARTIAL_HALF = 0x80

// One frame of it at a time (step); full once Link's life is
export function heartRefill (link) {
  let hearts = Math.ceil(link.currentLife) - 1
  let partial = Number.isInteger(link.currentLife) ? PARTIAL_FULL : PARTIAL_HALF - 1
  return {
    get full () {
      return hearts >= link.totalLife - 1 && partial >= PARTIAL_FULL
    },
    step () {
      if (this.full) {
        return
      }
      if (partial === PARTIAL_FULL) {
        hearts++
        partial = 0
      } else if (partial + REFILL_STEP <= PARTIAL_FULL) {
        partial += REFILL_STEP
      } else if (hearts < link.totalLife - 1) {
        hearts++
        partial = 0
      } else {
        partial = PARTIAL_FULL
      }
      link.currentLife = hearts + (partial === 0 ? 0 : partial < PARTIAL_HALF ? 0.5 : 1)
    }
  }
}
