'use strict'

// Graphics packs: other drawings for the sprites of the game, at any resolution, switched while playing. The
// logic does not change: every sprite keeps its place and size in the game (in NES pixels), only its images do.
// A pack lists its sprites by the names of the original ones; what it leaves out keeps the original drawing.
// "{palette}" in a name stands for any colour variant of the original (link_{palette}_east_normal_move: all the
// rings). A sprite keeps its number of images: a pack giving fewer repeats them, more are left out

const PALETTE_PLACEHOLDER = '{palette}'

// Places for frames of the given sizes ([{ width, height }], in pixels) in rows of at most maxWidth pixels:
// { places: [{ x, y }], width, height } of the atlas holding them
export function placeFrames (sizes, maxWidth) {
  const places = []
  let x = 0
  let y = 0
  let rowHeight = 0
  let width = 0
  for (const size of sizes) {
    if (x > 0 && x + size.width > maxWidth) {
      x = 0
      y += rowHeight
      rowHeight = 0
    }
    places.push({ x, y })
    x += size.width
    width = Math.max(width, x)
    rowHeight = Math.max(rowHeight, size.height)
  }
  return { places, width: Math.max(1, width), height: Math.max(1, y + rowHeight) }
}

// The names of the original sprites a name of a pack stands for
export function matchNames (name, names) {
  if (!name.includes(PALETTE_PLACEHOLDER)) {
    return names.includes(name) ? [name] : []
  }
  const [before, after] = name.split(PALETTE_PLACEHOLDER)
  return names.filter(other => other.length > before.length + after.length && other.startsWith(before) && other.endsWith(after))
}

// The names a name of a pack gives images to. Without {palette} it can be one the original does not have: a pose
// drawn only in green there (link_blue_east_normal_use) can exist in a pack, for the code that asks for it first
export function packNames (name, names) {
  return name.includes(PALETTE_PLACEHOLDER) ? matchNames(name, names) : [name]
}

// Adds the sprites only the pack has (create: name → sprite), and takes away those of the previous pack
export function syncSprites (sprites, originals, byName = {}, create) {
  for (const name of Object.keys(sprites)) {
    if (!(name in originals) && !(name in byName)) {
      delete sprites[name]
    }
  }
  for (const name of Object.keys(byName)) {
    sprites[name] ??= create(name)
  }
}

const brightness = colour => [0.3, 0.59, 0.11].reduce((sum, weight, i) => sum + weight * parseInt(colour.slice(i * 2, i * 2 + 2), 16), 0)

// The colours of an image ("rrggbb"), which can be many, put on fewer ones (those of a palette, an enemy hit): the
// darkest on the first one, the lightest on the last one, as many on each. A Map, old colour → new colour
export function rampColours (seen, colours) {
  const ranked = [...seen].sort((a, b) => brightness(a) - brightness(b))
  return new Map(ranked.map((colour, i) => [colour, colours[Math.floor(i * colours.length / ranked.length)]]))
}

// count images out of the given ones: repeated when there are fewer, the first ones when there are more
export function fitImages (images, count) {
  if (images.length === 0) {
    return []
  }
  return Array.from({ length: count }, (_, i) => images[i % images.length])
}

// Gives every sprite the images of the pack (byName: name → images), or its original ones (originals) when the
// pack has none for it, in place: the copies of the sprites (tiles, enemies) share their list of images
export function applyImages (sprites, originals, byName = {}) {
  for (const [name, sprite] of Object.entries(sprites)) {
    const original = originals[name]
    const images = byName[name] ? fitImages(byName[name], original?.length ?? byName[name].length) : original ?? []
    sprite.images.splice(0, sprite.images.length, ...images)
  }
}
