'use strict'

import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { flashImage } from './common'
import { Walker } from './walker'

// The bubble that flashes, read in the ROM (object $2B, bank 4 $843E): a walker (turning at $40) that nothing hurts nor
// stuns ($F0 of life), and the room is cleared without it (bank 5, $034D). It changes palette every frame ($15 & 3:
// Link's, 1, 2, then the place's). Touching Link is a hit that takes nothing from him: measured in $49, he flashes,
// is pushed back and the sound of a hit goes, as for any hit, and $4C (a slow timer, see slow-timers.js) is put at
// $10: while it is not 0 the sword does not come out (bank 5 $B2A1: the button A is not read), the items of B do.
// Flashing, Link is not touched, nor $4C put (measured). The bubble goes on its way
const SWORD_CURSE = 0x10
const PALETTE_FRAMES = 4
const PLACE_PALETTE = 3
// The flash counter giving the sprite palette 3, that of the place (see common.js, flashColours)
const PLACE_FLASH = 6

export class Bubble extends Walker {
  get mustDie () {
    return false
  }

  get isVulnerable () {
    return false
  }

  stun () {}

  fight (map, link) {
    if (this.isActive && !map.frozen && overlaps(this.getBox(), link.getContactBox()) && link.hurt(0, this.getBox())) {
      link.swordCurse = SWORD_CURSE
    }
  }

  drawBody (context) {
    const palette = this.steps % PALETTE_FRAMES
    const sprite = resource.getSprite('bubble_move')
    if (palette === PLACE_PALETTE) {
      flashImage(sprite?.images[0], PLACE_FLASH, this.placeType)?.draw(context, this.x, this.y, this.width, this.height)
      return
    }
    sprite?.images[palette]?.draw(context, this.x, this.y, this.width, this.height)
  }

  act (map, link) {
    this.placeType = map.type
    super.act(map, link)
  }
}
