'use strict'

import resource from '../../resource'
import { drawImage } from './common'
import { Flyer, PHASE_RESTING } from './flyer'

// A flying flower, measured in the ROM (object $1A): it flies over everything as the ghinis of the graves do (see
// flyer.js), taking off as soon as it is out of its cloud; when it chooses, it goes after the target if a random
// byte is $A0 or more, lands if it is under $20, and flies at random otherwise ($84B3). The sword only hurts it
// while it rests on the ground, and pushes it back as the walkers; it takes half a heart from Link at any time
const PEAHAT = { life: 2, contactDamage: 0.5 }
const PEAHAT_CHANCES = { chase: 0x60 / 256, land: 0x20 / 256 }
// The blades spin faster when it flies faster
const SPIN_SPEED_STEPS = 8 * 0xa0

class Peahat extends Flyer {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, PEAHAT, PEAHAT_CHANCES, random)
    this.spin = 0
  }

  get isVulnerable () {
    return super.isVulnerable && this.phase === PHASE_RESTING
  }

  // Out of its cloud
  start () {
    this.fly()
    this.takeOff()
  }

  act (map, link) {
    this.spin += this.speed
    super.act(map, link)
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('peahat_move'), Math.floor(this.spin / SPIN_SPEED_STEPS) % 2, this.x, this.y, this.width, this.height)
  }
}

export { Peahat }
